export function getEnv() {
  return {
    NODE_ENV: process.env.NODE_ENV ?? "development",
    API_PORT: Number(process.env.API_PORT ?? 3001),
    DATABASE_URL: process.env.DATABASE_URL ?? "",
    PILOT_SUBREDDITS: (process.env.PILOT_SUBREDDITS ?? "technology,news,gaming")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean),
    ENABLE_PUBLIC_SURFACES: (process.env.ENABLE_PUBLIC_SURFACES ?? "false") === "true"
  };
}

export async function fetchSubredditNew(subreddit) {
  console.log(`[reddit] placeholder fetch for r/${subreddit}`);
  return [
    {
      id: `demo-${subreddit}-1`,
      subreddit,
      author: "demo_user",
      body: `Placeholder content from r/${subreddit}`,
      created_at: new Date().toISOString()
    }
  ];
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const PORT = Number(process.env.API_PORT ?? 3001);
const ROOT = path.resolve(process.env.HOME || ".", "projects", "truth-lens");

function json(res, status, data) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data, null, 2));
}

function notFound(res) {
  json(res, 404, { error: "not_found" });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host}`);
  const parts = url.pathname.split("/").filter(Boolean);

  if (url.pathname === "/health") {
    return json(res, 200, {
      status: "ok",
      service: "truth-lens-api",
      time_utc: new Date().toISOString(),
      version: "v1"
    });
  }

  if (parts[0] === "post" && parts[1]) {
    return json(res, 200, {
      entity_type: "content",
      content_id: parts[1],
      message: "Post inspect stub"
    });
  }

  if (parts[0] === "account" && parts[1]) {
    return json(res, 200, {
      entity_type: "account",
      author_id: parts[1],
      message: "Account inspect stub"
    });
  }

  if (parts[0] === "cluster" && parts[1]) {
    return json(res, 200, {
      entity_type: "cluster",
      cluster_id: parts[1],
      message: "Cluster inspect stub"
    });
  }

  if (parts[0] === "narrative" && parts[1]) {
    return json(res, 200, {
      entity_type: "narrative",
      narrative_id: parts[1],
      message: "Narrative inspect stub"
    });
  }

  if (parts[0] === "tip" && parts[1]) {
    return json(res, 200, {
      entity_id: parts[1],
      available: false,
      tip: {
        headline: "Signs of suspicious coordination",
        body: `Placeholder PRO TIP for ${parts[1]}`,
        meaning: "This may indicate an attempt to shape interpretation.",
        caution: "This does not prove falsity or exact operator identity."
      }
    });
  }

  if (url.pathname === "/debug/root") {
    const exists = fs.existsSync(ROOT);
    return json(res, 200, { root: ROOT, exists });
  }

  return notFound(res);
});

server.listen(PORT, () => {
  console.log(`Truth Lens API running on port ${PORT}`);
});

import { fetchSubredditNew } from "../../../packages/reddit/src/fetch.ts";

const SUBS = (process.env.PILOT_SUBREDDITS ?? "technology,news,gaming")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

async function main() {
  console.log("Truth Lens worker started");
  console.log("Pilot subreddits:", SUBS.join(", "));

  for (const subreddit of SUBS) {
    const items = await fetchSubredditNew(subreddit);
    console.log(`[worker] ${subreddit}: ${items.length} items`);
  }

  console.log("Worker cycle complete");
}

main().catch((err) => {
  console.error("Worker failed:", err);
  process.exit(1);
});
